/* Force Multiplier · Improvement Laboratory test-choice practice
   All cases are fictional teaching vignettes. Reported p-values are illustrative, not calculated from case data. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;root.FMImprovementTests=api;})(typeof globalThis==='object'?globalThis:this,function(){'use strict';
const TESTS=[
{id:'mk',name:'Mann–Kendall trend',family:'Trends',question:'Is there a sustained monotonic change in an ordered time series?',use:'Ordered numerical observations when monotonic trend is of interest and a straight-line shape is not required.',h0:'There is no monotonic trend in the population over time.',assumptions:'Consistent measurements; account for serial correlation and seasonality before trusting inference.',warning:'A significant trend does not establish what caused the change.'},
{id:'pearson',name:'Pearson correlation',family:'Correlations',question:'How strong is the linear association between two paired numerical measures?',use:'Paired continuous measurements when a linear pattern is plausible.',h0:'The population Pearson linear correlation is zero.',assumptions:'Pairs are independent; check scatterplot for nonlinearity, outliers and appropriate inference assumptions.',warning:'Association does not establish causality. Do not split or reorder matched pairs.'},
{id:'spearman',name:'Spearman rank correlation',family:'Correlations',question:'Are two ordered measures monotonically associated?',use:'Paired ordered or ranked observations, especially when a monotonic relationship is not linear.',h0:'There is no population rank association between the two measures.',assumptions:'Paired independent observations; ties, sample size and the inference method affect p-values.',warning:'Rank association does not prove causation or necessarily imply a straight-line relationship.'},
{id:'welch',name:'Welch independent t-test',family:'Differences',question:'Do two independent groups have different population means?',use:'Two independent numerical groups when unequal population variances are possible.',h0:'The population means of the two independent groups are equal.',assumptions:'Independent observations; small highly skewed samples may not support t approximations.',warning:'Report effect size and confidence interval, not just p. Do not use for paired observations.'},
{id:'pooled',name:'Two-sample pooled t-test',family:'Differences',question:'Do two independent groups differ in mean with a justified equal-variance assumption?',use:'Two independent numerical groups when their population variances can reasonably be treated as equal.',h0:'The population means of the two independent groups are equal.',assumptions:'Independent observations, approximate normality for small samples, equal population variances.',warning:'If equal variance is uncertain, Welch is usually safer.'},
{id:'paired',name:'Paired t-test',family:'Differences',question:'Did the same items change on average between two measurements?',use:'Before/after values from the SAME assets or appropriately matched pairs.',h0:'The mean within-pair difference is zero.',assumptions:'Independent pairs; within-pair differences approximately normal for small samples.',warning:'Pair observations correctly. A before/after change alone does not prove the intervention caused it.'},
{id:'zmean',name:'Z-test for one mean',family:'Differences',question:'Does a sample mean differ from a target when the population standard deviation is known?',use:'One numerical sample with known population standard deviation and an appropriate sampling model.',h0:'The population mean equals the specified reference mean.',assumptions:'Population standard deviation is genuinely known; sample design/size must support normal approximation.',warning:'Do not substitute the sample standard deviation and call it a known-sigma Z-test.'},
{id:'zprop',name:'Z-test for two proportions',family:'Counts & rates',question:'Are two independent binomial event proportions different?',use:'Two independent sets of successes and totals with adequate expected counts for a normal approximation.',h0:'The two population event probabilities are equal.',assumptions:'Independent trials and groups; check success/failure counts and use Fisher exact for sparse 2×2 data.',warning:'A statistically detectable proportion difference may be operationally tiny.'},
{id:'anova',name:'One-way ANOVA F-test',family:'Differences',question:'Do any of three or more independent groups have different population means?',use:'Three or more independent numerical groups; compare between-group and within-group variation.',h0:'All population group means are equal.',assumptions:'Independent observations, approximately normal residuals and suitable variance assumptions.',warning:'Significant ANOVA says at least one mean differs; post-hoc work is needed to locate it.'},
{id:'mw',name:'Mann–Whitney U-test',family:'Differences',question:'Do two independent groups differ in their ranked distributions?',use:'Two independent numeric/ordinal groups without relying on a t-test mean comparison.',h0:'Under the specified model, the two population distributions are the same.',assumptions:'Independent observations and appropriate handling of ties; differing shapes complicate a median-only reading.',warning:'It does not universally test medians. Similar distribution shapes are needed for a shift interpretation.'},
{id:'kw',name:'Kruskal–Wallis H-test',family:'Differences',question:'Do three or more independent groups differ in their ranked distributions?',use:'Three or more independent ordinal/skewed measurement groups.',h0:'The population distributions of the independent groups are the same.',assumptions:'Independent observations; ties and different distribution shapes matter.',warning:'It does not identify which groups differ without follow-up comparisons.'},
{id:'chi-gof',name:'Chi-square goodness-of-fit',family:'Counts & rates',question:'Do categorical counts differ from a prespecified expected distribution?',use:'One sample of mutually exclusive categories, compared with prespecified expected proportions.',h0:'The population category proportions equal the prespecified expected proportions.',assumptions:'Independent counts and adequate expected counts; categories exhaustive and nonoverlapping.',warning:'Unexpected patterns require diagnosis; a chi-square result does not identify root cause.'},
{id:'chi-ind',name:'Chi-square independence',family:'Counts & rates',question:'Are two categorical variables associated?',use:'Contingency table of counts for two categorical variables.',h0:'The two categorical variables are independent in the population.',assumptions:'Independent counted units and adequate expected cell counts; use exact methods if sparse.',warning:'A relationship is not proof of cause; inspect which cells drive the association.'},
{id:'fvar',name:'F-test for two variances',family:'Variation',question:'Do two independent approximately normal populations have equal variances?',use:'Compare numerical variation across two independent groups under a normality assumption.',h0:'The two population variances are equal.',assumptions:'Independent samples drawn from approximately normal populations; sensitive to departures from normality.',warning:'Rejecting variance equality does not by itself mean the group means differ.'},
{id:'cochran',name:"Cochran's C test",family:'Variation',question:'Is the largest variance unusually large among several independent groups?',use:'Check a single unusually high sample variance among several groups with equal sample sizes.',h0:'All compared population variances are equal.',assumptions:'Independent normally distributed groups; standard form assumes equal sample sizes.',warning:'A large sample variance needs root-cause investigation, not automatic deletion of the group.'}
];
const CASES=[
{id:'mk',title:'12 months of repair turnaround',scenario:'You have 12 ordered monthly turnaround medians. You want to know whether a monotonic decline exists, without requiring a straight-line fit.',p:0.024,display:'Sample report: p = 0.024 · downward trend',effect:'The measured series trends downward; verify seasonality and operational size.',alternatives:['mk','pearson','welch','anova']},
{id:'pearson',title:'Work queue versus downtime',scenario:'For 18 independent operating days, each day has a queue-hours value paired with a downtime-hours value. The scatterplot looks approximately linear.',p:0.018,display:'Sample report: r = +0.61 · p = 0.018',effect:'There is evidence of a positive linear association, not a proven cause.',alternatives:['pearson','spearman','anova','chi-ind']},
{id:'spearman',title:'Priority ranks and wait ranks',scenario:'You have paired ordinal priority ratings and wait-time ranks. The relationship could be monotonic without being linear.',p:0.11,display:'Sample report: ρ = −0.32 · p = 0.110',effect:'The sample evidence is insufficient to reject zero rank association.',alternatives:['pearson','spearman','welch','mk']},
{id:'welch',title:'Different teams, unequal variability',scenario:'Two unrelated maintenance teams report independent numerical turnaround times with visibly different spreads. Compare population mean turnaround time.',p:0.027,display:'Sample report: mean difference = −1.4 h · p = 0.027',effect:'A mean difference is supported; verify uncertainty and practical significance.',alternatives:['pooled','paired','welch','mw']},
{id:'pooled',title:'Two independent stable processes',scenario:'Two independent randomly selected work groups have approximately normal durations; the equal-population-variance assumption has strong support. Compare their means.',p:0.071,display:'Sample report: difference = +0.4 h · p = 0.071',effect:'At α = .05 this does not establish a difference; it does not prove the means are equal.',alternatives:['pooled','paired','anova','cochran']},
{id:'paired',title:'Same assets before and after',scenario:'You record repair duration on the SAME 20 assets before and after a process change. You want the average within-asset change.',p:0.006,display:'Sample report: mean paired change = −0.8 h · p = 0.006',effect:'The within-pair mean change is supported; beware unrelated time changes.',alternatives:['welch','paired','pooled','kw']},
{id:'zmean',title:'Known standard deviation',scenario:'An audit uses a random sample of 64 transactions. The population standard deviation was independently established and is known. Does the mean exceed the specified target?',p:0.008,display:'Sample report: Z = +2.65 · p = 0.008',effect:'There is evidence that the mean differs from the target under the model.',alternatives:['zmean','paired','fvar','zprop']},
{id:'zprop',title:'Two independent completion rates',scenario:'Compare the percent of jobs completed on time between two independent large groups. You have the successful counts and total counts for each.',p:0.043,display:'Sample report: proportion difference = 6 percentage points · p = 0.043',effect:'A difference in event proportions is supported; assess operational size.',alternatives:['zprop','chi-gof','zmean','welch']},
{id:'anova',title:'Three shops, different means?',scenario:'Three independent shops supply numerical average delays. You want to test whether ANY shop mean differs, rather than make repeated unadjusted pairwise t-tests.',p:0.014,display:'Sample report: ANOVA F-test p = 0.014',effect:'At least one mean differs; follow-up comparisons must identify which.',alternatives:['anova','kw','pooled','fvar']},
{id:'mw',title:'Two independent skewed repair samples',scenario:'Two independent groups have strongly skewed repair-duration observations. You want to compare their rank distributions rather than assume a mean-based t-test model.',p:0.031,display:'Sample report: U test p = 0.031',effect:'Evidence suggests the distributions differ; not automatically a median difference.',alternatives:['welch','mw','kw','spearman']},
{id:'kw',title:'Four shops, ordinal ratings',scenario:'Four independent shops receive ordinal workload scores. You want to determine whether the score distributions differ across the groups.',p:0.22,display:'Sample report: H test p = 0.220',effect:'No statistically clear difference at .05; do not declare equivalence.',alternatives:['kw','anova','mw','chi-ind']},
{id:'chi-gof',title:'Failure-type mix versus baseline',scenario:'You counted failures in four mutually exclusive categories. Test whether their observed counts fit a PREDEFINED expected mix.',p:0.02,display:'Sample report: χ² goodness-of-fit p = 0.020',effect:'Observed category distribution differs from the baseline model.',alternatives:['chi-gof','chi-ind','anova','zprop']},
{id:'chi-ind',title:'Equipment class versus repeat events',scenario:'You have a count table cross-classifying equipment classes with repeat-failure Yes/No. Test whether the two categorical variables are associated.',p:0.032,display:'Sample report: χ² independence p = 0.032',effect:'An association exists under test assumptions; cause remains unproven.',alternatives:['chi-ind','chi-gof','pearson','zmean']},
{id:'fvar',title:'Is one process less consistent?',scenario:'You have two independent approximately normal groups of numerical repair times. You want to compare their POPULATION VARIANCES, not their means.',p:0.30,display:'Sample report: F variance p = 0.300',effect:'Insufficient evidence of a variance difference at .05.',alternatives:['fvar','cochran','pooled','anova']},
{id:'cochran',title:'One unusually variable shop',scenario:'Five independent approximately normal shops provide equal-size duration samples. One sample variance is much larger than the others.',p:0.04,display:"Sample report: Cochran's C p = 0.040",effect:'The largest observed variance is unusually high under the equal-variance model.',alternatives:['fvar','cochran','anova','kw']}
];
function byId(id){return TESTS.find(t=>t.id===id)}
function caseByIndex(index){const n=CASES.length;return CASES[((index%n)+n)%n];}
function orderOptions(options,idx,stage=0){const copy=options.slice(),turn=(idx*7+stage*3+1)%copy.length;return copy.slice(turn).concat(copy.slice(0,turn));}
function optionSet(idx,stage){const c=caseByIndex(idx),t=byId(c.id);
if(stage===0)return orderOptions(c.alternatives,idx,stage).map(id=>({id,label:byId(id).name,correct:id===c.id}));
if(stage===1)return orderOptions([{id:'h0',label:t.h0,correct:true},{id:'sample',label:'Every observed sample value is identical and cannot vary.',correct:false},{id:'cause',label:'The suspected intervention must be the cause of any association.',correct:false}],idx,stage);
if(stage===2)return orderOptions([{id:'reject',label:'Reject the specified null; inspect effect, assumptions, and uncertainty.',correct:c.p<.05},{id:'notreject',label:'Do not reject the null; an effect remains possible.',correct:c.p>=.05},{id:'cause',label:'The p-value establishes that the suspected intervention caused the result.',correct:false},{id:'prob',label:'The p-value is the probability the null hypothesis is true.',correct:false}],idx,stage);
return [];
}
function grade(index,stage,id){const opts=optionSet(index,stage),o=opts.find(o=>o.id===id);return {ok:!!o?.correct,correct:opts.find(x=>x.correct)?.id||null};}
return {TESTS,CASES,byId,caseByIndex,optionSet,grade};
});
